CREATE OR REPLACE FUNCTION public.rosa_historico()
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE f uuid; c public.rosa_conversas; BEGIN f:=public.portal_cuidados_funcionario(); IF f IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado' USING ERRCODE='42501'; END IF; INSERT INTO public.rosa_conversas(funcionario_id,tenant_id) SELECT id,tenant_id FROM public.funcionarios WHERE id=f ON CONFLICT(funcionario_id) DO NOTHING; SELECT * INTO c FROM public.rosa_conversas WHERE funcionario_id=f; RETURN jsonb_build_object('conversa_id',c.id,'funcionario_id',f,'tenant_id',c.tenant_id,'modulos',to_jsonb(COALESCE(public.modulos_funcionario(f),'{}'::text[])),'mensagens',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',m.id,'role',m.papel,'parts',m.partes) ORDER BY m.created_at,m.id) FROM public.rosa_mensagens m WHERE m.conversa_id=c.id),'[]'::jsonb),'orientacoes',COALESCE((SELECT jsonb_agg(orientacao_aprovada) FROM public.rosa_orientacoes WHERE status='aprovada' AND tenant_id IS NOT DISTINCT FROM c.tenant_id),'[]'::jsonb)); END $function$;